Algorithm Negative
  Dimension image[4, 4] As Integer;
  For f <- 0 To 3 Do
    For c <- 0 To 3 Do
      Read image[f, c];
    EndFor
  EndFor
  For f <- 0 To 3 Do
    Define line As String <- "";
    For c <- 0 To 3 Do
      line <- line + toText(1 - image[f, c]);
    EndFor
    Write line;
  EndFor
EndAlgorithm
